<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionRef;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Service\Visibility\ThemeVersionVisibilityService;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class ThemeVersionRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly ThemeVersionVisibilityService $visibility,
        private readonly ThemeVersionReadGateway $reader
    ) {
    }

    public function allowRetrieve(?ThemeVersionRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Theme version");
        $span = $this->startSpan("Check allow of retrieve usecase for Theme version");
        try {
            $result = $this->dispatcher->dispatch(new ThemeVersionRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?ThemeVersionRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Theme version");
        $span = $this->startSpan("Check hidden fields usecase for Theme version");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): ThemeVersionRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Theme version");
        $span = $this->startSpan("Run retrieve usecase for Theme version");
        try {
            $ref = new ThemeVersionRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Theme version');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new ThemeVersionRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
